import { ConstructibleHasTagType } from "#base/ui/utilities/utilities-tags.js";

// Unit cinematics are mostly working, but there are edge cases with
// units near buildings and units in certain states that aren't ideal for cinematics
const ENABLE_UNIT_CINEMATICS = false;

enum POIType {
	CITY = "City",
	WONDER = "Wonder",
	UNIT = "Unit",
	BUILDING = "Building",
	VICTORY = "Victory", // This type is used for the first cinematic in a victory sequence, which may show a specific asset related to the victory type instead of a plot
}

interface PointOfInterest {
	plot: float2;
	desc: string;
	score: number;
	type: POIType;
	camera: DynamicCameraParams;
	cinematic?: boolean;
}

const MAX_POINTS_OF_INTEREST = 10;
const MIN_CITY_POPULATION = 4;
const CAPITAL_SCORE = 100;
const POPULATION_SCORE = 1;
const WONDER_SCORE_AGE = 20;
const WONDER_SCORE_START = 50;
const WONDER_SCORE_DEC = 10; // reduced score for successive wonders
const UNIT_PROMOTION_SCORE = 10;
const UNIT_FORMATION_SCORE = 5;

// eslint-disable-next-line @typescript-eslint/no-inferrable-types
const MIN_UNIT_PROMOTION: number = 1; // explicit type avoids linter error from comparing to 0 below

const CINEMATIC_DURATION = 9.5;

const BASE_FLYOVER_CAMERA_PARAMS: FlyoverParams = {
	focusHeight: 10,
	cameraHeight: 85,
	focusRange: 64,
	targetDistance: 64 * 2.5,
	endpointRange: 64,
	curvature: 0.5,
	panStrength: 0.35,
	maxMovement: 150,
	primaryAngle: 180,
	duration: CINEMATIC_DURATION,
	easeInFactor: 1,
	easeOutFactor: 1,
};
const CITY_CAMERA_PARAMS: FlyoverParams = {
	...BASE_FLYOVER_CAMERA_PARAMS,
};
const UNIT_CAMERA_PARAMS: FlyoverParams = {
	...BASE_FLYOVER_CAMERA_PARAMS,
};
const WONDER_CAMERA_PARAMS: FlyoverParams = {
	...BASE_FLYOVER_CAMERA_PARAMS,
};
const FIRST_FLYTHROUGH_CAMERA_PARAMS: FlyoverParams = {
	...BASE_FLYOVER_CAMERA_PARAMS,
	easeInFactor: 1.0, // Ease in only the first animation
};

// These are the default camera params for each victory type, but may be overridden by specific assets
const BASE_VICTORY_CAMERA_PARAMS: DynamicCameraParams = {
	focusHeight: 35,
	cameraHeight: 80,
	orbitRadius: 150,
	duration: 12,
	easeInFactor: 1.5,
	easeOutFactor: 1.0,
	arcHeight: 0,
	maxArcAngle: 60,
	leadInRange: 0,
	endAngleOffset: 10,
};
const SCIENCE_VICTORY_CAMERA_PARAMS: DynamicCameraParams = {
	...BASE_VICTORY_CAMERA_PARAMS,
	focusHeight: 75,
	cameraHeight: 150,
	orbitRadius: 190,
	duration: 12.8,
	easeInFactor: 2,
	easeOutFactor: 4,
	arcHeight: 10,
	maxArcAngle: -60,
};
const MILITARY_VICTORY_CAMERA_PARAMS: DynamicCameraParams = {
	...BASE_VICTORY_CAMERA_PARAMS,
};
const DOMINATION_VICTORY_CAMERA_PARAMS: DynamicCameraParams = {
	...BASE_VICTORY_CAMERA_PARAMS,
};
const SCORE_VICTORY_CAMERA_PARAMS: DynamicCameraParams = {
	...BASE_VICTORY_CAMERA_PARAMS,
};
const CULTURE_VICTORY_CAMERA_PARAMS: DynamicCameraParams = {
	...BASE_VICTORY_CAMERA_PARAMS,
};
const ECONOMIC_VICTORY_CAMERA_PARAMS: DynamicCameraParams = {
	...BASE_VICTORY_CAMERA_PARAMS,
};

function getVictoryCinematicCameraParams(victoryClass: string): DynamicCameraParams {
	// Check for a specific asset for the current cinematic
	if (victoryClass.length > 0) {
		const asset: string = victoryClass + "_CAMERA_SETTINGS";
		const params = Camera.findDynamicCameraSettings(asset);
		if (params) {
			return params;
		}
	}

	if (victoryClass == "VICTORY_CLASS_SCIENCE") {
		return SCIENCE_VICTORY_CAMERA_PARAMS;
	}

	if (victoryClass == "VICTORY_CLASS_MILITARY") {
		return MILITARY_VICTORY_CAMERA_PARAMS;
	}

	if (victoryClass == "VICTORY_CLASS_DOMINATION") {
		return DOMINATION_VICTORY_CAMERA_PARAMS;
	}

	if (victoryClass == "VICTORY_CLASS_SCORE") {
		return SCORE_VICTORY_CAMERA_PARAMS;
	}

	if (victoryClass == "VICTORY_CLASS_CULTURE") {
		return CULTURE_VICTORY_CAMERA_PARAMS;
	}

	if (victoryClass == "VICTORY_CLASS_ECONOMIC") {
		return ECONOMIC_VICTORY_CAMERA_PARAMS;
	}

	// Fallback to generic camera settings
	let params = Camera.findDynamicCameraSettings("GAME_VICTORY_DEFAULT_CAMERA_SETTINGS");
	if (!params) {
		params = Camera.findDynamicCameraSettings("DEFAULT_CAMERA_SETTINGS");
	}
	return params ? params : CITY_CAMERA_PARAMS;
}

export interface VictoryData {
	victoryClass: string;
	isDefeat: boolean;
}

export class EndgameCinematicManager {
	private pois: PointOfInterest[] = [];
	private poiIndex = 0;
	private playVFX = false;
	private looping = false;
	private running = false;
	private camera = false;
	private units = false;
	private firstRun = false;
	private timeout?: number;
	private lastPlot?: float2;
	private currentPoi?: PointOfInterest;
	private cinematic?: WorldUI.Cinematic;
	private CinematicVFXModelGroup: WorldUI.ModelGroup | null = null;
	private onComplete?: () => void;
	private vfxQueue: string[] = [];

	private awaitCinematicListener = this.awaitCinematic.bind(this);

	public static instance = new EndgameCinematicManager();

	start(victory?: VictoryData, onComplete?: () => void) {
		if (this.running) {
			this.stop();
		}

		this.pois = this.getPointsOfInterest(victory);
		this.poiIndex = 0;
		this.looping = victory == undefined;
		this.playVFX = victory ? !victory.isDefeat : true;
		this.onComplete = onComplete;
		this.running = true;
		this.firstRun = true;
		this.CinematicVFXModelGroup = WorldUI.createModelGroup("CinematicVFXModelGroup");
		this.nextCinematic();
	}

	stop() {
		if (this.running) {
			this.endCinematic();
			if (this.CinematicVFXModelGroup) {
				this.CinematicVFXModelGroup.clear(true); // clean up any vfx
				this.CinematicVFXModelGroup.destroy();
				this.CinematicVFXModelGroup = null;
			}
			if (this.timeout != undefined) {
				window.clearTimeout(this.timeout);
				this.timeout = undefined;
			}
			this.pois = [];
			this.running = false;
		}
	}

	private isCoastTile(plot: float2): boolean {
		const terrainType = GameplayMap.getTerrainType(plot.x, plot.y);
		return GameInfo.Terrains.lookup(terrainType)?.TerrainType === "TERRAIN_COAST";
	}

	private startCinematic(poi: PointOfInterest) {
		if (poi.type == POIType.UNIT) {
			// TODO this won't make units visible if they are on an urban tile
			WorldUI.setUnitVisibility(true);
			this.units = true;
		}

		this.currentPoi = poi;
		this.lastPlot = poi.plot;
		if (poi.cinematic != undefined && poi.cinematic) {
			this.cinematic = WorldUI.requestCinematic(poi.plot);
		} else if (poi.plot != undefined) {
			// Make a list of the plot point for all of the surrounding plots to spawn VFX in them as well, which makes the cinematic more visually interesting.

			const surroundingPlots: float2[] = [];
			surroundingPlots.push(poi.plot);

			for (let iDirection: DirectionTypes = 0; iDirection < DirectionTypes.NUM_DIRECTION_TYPES; iDirection++) {
				const adjacentPlot = GameplayMap.getAdjacentPlotLocation(poi.plot, iDirection);
				console.error("Adjacent Plot", iDirection);
				// if the plot is not valid we add the center plot again to fill out the VFX visuals
				if (adjacentPlot && !this.isCoastTile(adjacentPlot)) {
					surroundingPlots.push(adjacentPlot);
				} else {
					surroundingPlots.push(poi.plot);
				}
			}

			if (this.CinematicVFXModelGroup) {
				this.CinematicVFXModelGroup.clear();
			}
			for (const plot of surroundingPlots) {
				// Play Fireworks
				const fireworksScale = 1;
				if (this.CinematicVFXModelGroup) {
					if (this.playVFX) {
						this.CinematicVFXModelGroup.addModelAtPlot(
							this.getCinematicPlotVFXAssetName(),
							plot,
							{ x: 0, y: 0, z: 0 },
							{ initialState: "REVEAL", placement: PlacementMode.WATER, scale: fireworksScale },
						);
					}
				}
			}
		}

		this.awaitCinematic();
	}

	private awaitCinematic() {
		if (this.currentPoi == undefined || this.camera) {
			// The wonder movie was stopped or is already playing
			return;
		}

		if (this.cinematic && !this.cinematic.isReady()) {
			// Cinematic is not ready, try again next frame
			window.requestAnimationFrame(this.awaitCinematicListener);
			return;
		}

		this.cinematic?.start();
		if (this.currentPoi.type == POIType.VICTORY) {
			Camera.pushDynamicCamera(this.currentPoi.plot, this.currentPoi.camera);
		} else {
			Camera.pushFlyoverCamera(this.currentPoi.plot, this.currentPoi.camera);
		}
		this.camera = true;
	}

	private endCinematic() {
		if (this.cinematic) {
			this.cinematic.destroy();
			this.cinematic = undefined;
		}

		if (this.camera) {
			Camera.popCamera();
			this.camera = false;
		}

		if (this.units) {
			WorldUI.setUnitVisibility(false);
			this.units = false;
		}

		this.currentPoi = undefined;
	}

	private nextCinematic() {
		this.endCinematic();

		if (this.pois.length === 0) {
			this.stop();
			this.onComplete?.();
			return;
		}

		if (!this.looping && this.poiIndex >= this.pois.length) {
			this.stop();
			this.onComplete?.();
			return;
		}

		// Greedy algorithm to minimize back-to-back animations in the same location
		// If the next PoI is too close, look ahead and randomly reorder with a better option
		if (this.lastPlot) {
			const MIN_DISTANCE = 3;
			const distance = (a: float2, b: float2) => {
				return GameplayMap.getPlotDistance(a.x, a.y, b.x, b.y);
			};

			const next = this.pois[this.poiIndex % this.pois.length];
			const dist = distance(this.lastPlot, next.plot);
			if (dist < MIN_DISTANCE) {
				const options: number[] = [];
				for (let i = 0; i < this.pois.length; i++) {
					const index = (this.poiIndex + i) % this.pois.length;
					if (distance(this.lastPlot, this.pois[index].plot) >= MIN_DISTANCE) {
						options.push(index);
					}
				}

				if (options.length > 0) {
					const swapIndex = options[Math.floor(Math.random() * options.length)];
					const nextIndex = this.poiIndex % this.pois.length;
					this.pois[nextIndex] = this.pois[swapIndex];
					this.pois[swapIndex] = next;
				}
			}
		}

		let poi = this.pois[this.poiIndex % this.pois.length];
		if (this.looping && this.firstRun) {
			poi = { ...poi, camera: FIRST_FLYTHROUGH_CAMERA_PARAMS };
			this.firstRun = false;
		}
		this.poiIndex++;

		this.startCinematic(poi);
		if (poi != undefined) {
			if (poi.camera != undefined && poi.camera.duration != undefined) {
				this.timeout = window.setTimeout(this.nextCinematic.bind(this), poi.camera.duration * 1000);
			} else {
				this.timeout = window.setTimeout(this.nextCinematic.bind(this), CINEMATIC_DURATION * 1000);
			}
		}
	}

	private getPointsOfInterest(victory?: VictoryData): PointOfInterest[] {
		const player = Players.get(GameContext.localPlayerID);
		if (!player) {
			return [];
		}

		const results: PointOfInterest[] = [];

		const addCities = (scoreFunc: (city: City) => number) => {
			const playerCities = player.Cities;
			if (playerCities) {
				const cities = playerCities.getCities();
				for (const city of cities) {
					const score = scoreFunc(city);
					if (score > 0) {
						results.push({
							plot: city.location,
							desc: Locale.compose(city.name),
							score,
							type: POIType.CITY,
							camera: CITY_CAMERA_PARAMS,
						});
					}
				}
			}
		};

		const addWonders = (scoreFunc: (wonder: Constructible) => number) => {
			const wonders = player.Constructibles?.getWonders(player.id);
			if (wonders) {
				for (const wonder of wonders) {
					const constructible = Constructibles.getByComponentID(wonder);
					const info = constructible ? GameInfo.Constructibles.lookup(constructible.type) : undefined;
					if (constructible && info && constructible.complete && !constructible.damaged) {
						const score = scoreFunc(constructible);
						if (score > 0) {
							results.push({
								plot: constructible.location,
								desc: Locale.compose(info.Name),
								score,
								type: POIType.WONDER,
								camera: WONDER_CAMERA_PARAMS,
							});
						}
					}
				}
			}
		};

		const addBuildings = (scoreFunc: (building: Constructible, def: ConstructibleDefinition) => number) => {
			const constructibles = player.Constructibles?.getConstructibles();
			if (constructibles) {
				for (const constructible of constructibles) {
					const info = GameInfo.Constructibles.lookup(constructible.type);
					if (info && constructible.complete && !constructible.damaged) {
						const score = scoreFunc(constructible, info);
						if (score > 0) {
							results.push({
								plot: constructible.location,
								desc: Locale.compose(info.Name),
								score,
								type: POIType.BUILDING,
								camera: CITY_CAMERA_PARAMS,
							});
						}
					}
				}
			}
		};

		const addUnits = (scoreFunc: (unit: Unit) => number) => {
			const playerUnits = player.Units?.getUnits();
			if (ENABLE_UNIT_CINEMATICS && playerUnits) {
				// Add units based on callback, excluding units that are  sleeping/healing or on developed tiles
				const excludedDistricts = [DistrictTypes.WONDER, DistrictTypes.URBAN, DistrictTypes.CITY_CENTER];
				const excludedActivities = [UnitActivityTypes.HEAL, UnitActivityTypes.SLEEP];
				for (const unit of playerUnits) {
					if (excludedActivities.includes(unit.activityType)) continue;
					const district = Districts.getAtLocation(unit.location);
					if (district && excludedDistricts.includes(district.type)) continue;

					const score = scoreFunc(unit);
					if (score > 0) {
						results.push({
							plot: unit.location,
							desc: `UNIT: ${unit.name}`,
							score: score,
							type: POIType.UNIT,
							camera: UNIT_CAMERA_PARAMS,
						});
					}
				}
			}
		};

		const addCapitalFallback = () => {
			if (results.length == 0) {
				addCities((city: City) => {
					if (!city.isCapital) return 0;
					return CAPITAL_SCORE + city.population * POPULATION_SCORE;
				});
			}
		};

		let maxResults = MAX_POINTS_OF_INTEREST;
		if (victory != undefined) {
			maxResults = 1;
			switch (victory.victoryClass) {
				case "VICTORY_CLASS_SCIENCE": {
					player.Constructibles?.getConstructibles().forEach((constructible) => {
						// Find operational launchpads in a valid city
						const def = GameInfo.Constructibles.lookup(constructible.type);
						if (!constructible.complete || constructible.damaged) return;
						if (!def || def.ConstructibleType != "BUILDING_LAUNCH_PAD") return;
						const city = Cities.get(constructible.cityId);
						if (!city) return;

						// Prioritize launch pad in capital, but otherwise pick the biggest city
						const score = city.population + (city.isCapital ? 100 : 0);
						results.push({
							plot: constructible.location,
							desc: Locale.compose(def.Name),
							score,
							type: POIType.BUILDING,
							camera: getVictoryCinematicCameraParams(victory.victoryClass),
							cinematic: true,
						});
					});

					addCapitalFallback();
					break;
				}

				case "VICTORY_CLASS_CULTURE":
					// Worlds Faire > Latest Wonder > Capital
					// TODO prioritize worlds faire
					addWonders((wonder: Constructible) => {
						let age = 1; // antiquity
						switch (wonder.ageControlled) {
							case Database.makeHash("AGE_EXPLORATION"):
								age = 2;
								break;
							case Database.makeHash("AGE_MODERN"):
								age = 3;
								break;
						}

						const maxTurns = Game.maxTurns > 0 ? Game.maxTurns : 1000;
						age += wonder.turnControlled / maxTurns; // add a fraction between each age
						return age * WONDER_SCORE_AGE;
					});
					addCapitalFallback();
					break;

				case "VICTORY_CLASS_ECONOMIC":
					// Highest-Value Econ Building > Capital
					// TODO train station animation?
					addBuildings((building, def) => {
						if (ConstructibleHasTagType(def.ConstructibleType, "GOLD")) {
							const isCapital = Cities.get(building.cityId)?.isCapital ?? false;
							return def.Cost + (isCapital ? 200 : 100); // prefer econ building in capital
						}
						return 0;
					});
					addCapitalFallback();
					break;

				case "VICTORY_CLASS_MILITARY":
					// Ranked+Packed Commanders > Capital
					addUnits((unit: Unit) => {
						const promotions = unit.Experience?.getNumPromotions;
						if (promotions) {
							if (MIN_UNIT_PROMOTION == 0 || promotions >= MIN_UNIT_PROMOTION) {
								const score = promotions * UNIT_PROMOTION_SCORE;
								return score + unit.formationUnitCount * UNIT_FORMATION_SCORE;
							}
						}
						return 0;
					});

					// Largest captured city, if any are at least half the population of the player's capital
					{
						const capital = player.Cities?.getCapital();
						const minPopulation = capital ? capital.population / 2 : MIN_CITY_POPULATION;
						addCities((city: City) => {
							if (city.isTown && !city.isOriginalCapital) return 0;
							if (city.originalOwner == GameContext.localPlayerID) return 0;
							if (city.population >= minPopulation) {
								// isOriginalCapital is constant after the city is founded
								const score = city.isOriginalCapital ? CAPITAL_SCORE : 0;
								return score + city.population * POPULATION_SCORE;
							}
							return 0;
						});
					}

					addCapitalFallback();
					break;

				default:
					// Only add capital
					addCapitalFallback();
					break;
			}

			// Override the camera on all of the results to be the victory cinematic camera when a victory type is passed in
			for (const entry of results) {
				entry.camera = getVictoryCinematicCameraParams(victory.victoryClass);
				entry.type = POIType.VICTORY;
			}
		} else {
			// Add cities above population threshold, capital is always included
			addCities((city: City) => {
				if (city.isTown) return 0;
				if (city.population >= MIN_CITY_POPULATION || city.isCapital) {
					const score = city.isCapital ? CAPITAL_SCORE : 0;
					return score + city.population * POPULATION_SCORE;
				}
				return 0;
			});

			// Add commander units, scored by promotions and units in formation
			addUnits((unit: Unit) => {
				const promotions = unit.Experience?.getNumPromotions;
				if (promotions) {
					if (MIN_UNIT_PROMOTION == 0 || promotions >= MIN_UNIT_PROMOTION) {
						const score = promotions * UNIT_PROMOTION_SCORE;
						return score + unit.formationUnitCount * UNIT_FORMATION_SCORE;
					}
				}
				return 0;
			});

			// Add assortment of wonders with descending scores
			let wonderScore = WONDER_SCORE_START;
			addWonders((_wonder: Constructible) => {
				const score = wonderScore;
				wonderScore -= WONDER_SCORE_DEC;
				return score;
			});

			// Pad with additional urban plots so there's enough different locations in the sequence
			if (results.length < maxResults) {
				const playerCities = player.Cities;
				if (playerCities) {
					let cities = playerCities.getCities();
					cities.sort((a: City, b: City) => b.population - a.population);
					cities = cities.slice(0, maxResults);

					const missing = maxResults - results.length;
					const perCity = Math.ceil(missing / cities.length);
					for (const city of cities) {
						const districts = city.Districts?.getIdsOfType(DistrictTypes.URBAN);

						const plots: float2[] = [];
						districts?.forEach((id) => {
							const district = Districts.get(id);
							if (district && !this.isCoastTile(district.location)) {
								plots.push(district.location);
							}
						});

						for (let i = 0; i < perCity; i++) {
							if (plots.length == 0) break;

							const index = Math.floor(Math.random() * plots.length);
							results.push({
								plot: plots[index],
								desc: Locale.compose(city.name),
								score: Math.random() * city.population * POPULATION_SCORE,
								type: POIType.CITY,
								camera: CITY_CAMERA_PARAMS,
							});

							plots[index] = plots[plots.length - 1];
							plots.pop();
						}
					}
				}
			}
		}

		// Return the top 10 results
		results.sort((a: PointOfInterest, b: PointOfInterest) => b.score - a.score);
		return results.slice(0, maxResults);
	}

	private getCinematicPlotVFXAssetName(): string {
		const vfxList = [
			"Cinematic_Victory_VFX",
			"Cinematic_Victory_VFX_02",
			"Cinematic_Victory_VFX_03",
			"Cinematic_Victory_VFX_04",
			"Cinematic_Victory_VFX_05",
			"Cinematic_Victory_VFX_06",
			"Cinematic_Victory_VFX_07",
		];

		if (this.vfxQueue.length === 0) {
			this.vfxQueue = [...vfxList];
			for (let i = this.vfxQueue.length - 1; i > 0; i--) {
				const j = Math.floor(Math.random() * (i + 1));
				[this.vfxQueue[i], this.vfxQueue[j]] = [this.vfxQueue[j], this.vfxQueue[i]];
			}
		}

		return this.vfxQueue.pop()!;
	}
}
